const body = $json.body;
let phone = 'test_chat';
let text = '';

if (body && body.entry && body.entry[0].changes && body.entry[0].changes[0].value && body.entry[0].changes[0].value.messages) {
  const msg = body.entry[0].changes[0].value.messages[0];
  phone = msg.from;
  text = msg.text ? msg.text.body : '';
} else if ($json.chatInput) {
  text = $json.chatInput;
  phone = $json.sessionId || 'test_chat';
}

if (!text) {
  return [];
}

return [{
  json: {
    sessionId: phone,
    patient_phone: phone,
    chatInput: text
  }
}];
